<script setup>import{onMounted,ref}from'vue';import{request}from'../api';const org='DEMO-DG',data=ref({assets:[],issues:[],runs:[],lineage:[]}),busy=ref(false),error=ref('');async function load(){try{data.value=await request('/api/governance/dashboard?organizationCode='+org)}catch(e){error.value=e.message}}async function scenario(){busy.value=true;error.value='';try{const stamp=Date.now(),source=await request('/api/governance/assets',{method:'POST',body:JSON.stringify({organizationCode:org,assetCode:'SRC-'+stamp,name:'客户源数据',dataDomain:'客户域',owner:'数据平台主管',classification:'内部'})}),target=await request('/api/governance/assets',{method:'POST',body:JSON.stringify({organizationCode:org,assetCode:'MDM-'+stamp,name:'客户主数据',dataDomain:'客户域',owner:'数据平台主管',classification:'重要'})});await request(`/api/governance/assets/${target.id}/rules`,{method:'POST',body:JSON.stringify({ruleCode:'COMPLETE-95',ruleType:'COMPLETENESS',expression:'customer_name is not null',threshold:95})});await request(`/api/governance/assets/${target.id}/submit`,{method:'POST'});await request(`/api/admin/governance/assets/${target.id}/publish`,{method:'POST'});await request(`/api/governance/assets/${target.id}/quality-runs`,{method:'POST',body:JSON.stringify({runNo:'RUN-'+stamp,totalRows:10000,failedRows:800})});await request('/api/governance/lineage',{method:'POST',body:JSON.stringify({organizationCode:org,sourceCode:source.assetCode,targetCode:target.assetCode,transformation:'标准化、去重与主键合并'})});await load()}catch(e){error.value=e.message}finally{busy.value=false}}onMounted(load)</script>
<template><section class="dw-head"><div><span>DATA GOVERNANCE OPERATIONS</span><h3>数据资产与质量运营中心</h3><p>真实管理数据资产发布、规则执行、质量问题和血缘链路。</p></div><button @click="scenario" :disabled="busy">{{busy?'正在执行…':'创建完整演示闭环'}}</button></section><p v-if="error" class="dw-error">{{error}}（发布步骤需要管理员账号）</p><section class="dw-metrics"><article><span>数据资产</span><b>{{data.assets.length}}</b></article><article><span>开放问题</span><b>{{data.issues.filter(i=>i.status!=='CLOSED').length}}</b></article><article><span>质量执行</span><b>{{data.runs.length}}</b></article><article><span>血缘关系</span><b>{{data.lineage.length}}</b></article></section><section class="dw-grid"><article><h4>数据资产</h4><table><tr><th>编码/名称</th><th>责任人</th><th>质量</th><th>状态</th></tr><tr v-for="a in data.assets" :key="a.id"><td><b>{{a.assetCode}}</b><small>{{a.name}}</small></td><td>{{a.owner}}</td><td>{{a.qualityScore}}%</td><td><i>{{a.status}}</i></td></tr></table></article><article><h4>质量问题</h4><div class="issue" v-for="i in data.issues" :key="i.id"><b>{{i.issueNo}} · {{i.severity}}</b><span>{{i.description}}</span><i>{{i.status}}</i></div></article></section></template>
<style scoped>.dw-head{display:flex;justify-content:space-between;align-items:end;background:#173f49;color:#fff;padding:26px 30px;border-radius:14px}.dw-head span{font-size:11px;letter-spacing:.16em;color:#9fc4c9}.dw-head h3{font-size:25px;margin:7px 0}.dw-head p{margin:0;color:#c7dbde}.dw-head button{background:#f3b85b;border:0;border-radius:8px;padding:12px 18px;font-weight:700}.dw-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.dw-metrics article,.dw-grid article{background:#fff;border:1px solid #dfe6e7;border-radius:12px;padding:20px}.dw-metrics span{color:#6d7b80}.dw-metrics b{display:block;font-size:30px;margin-top:8px}.dw-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:16px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px;border-bottom:1px solid #edf0f1}td small{display:block;color:#718087}.issue{display:grid;gap:5px;padding:12px 0;border-bottom:1px solid #edf0f1}.issue span{color:#607178}.issue i,td i{font-style:normal;color:#246b55}.dw-error{color:#a43b35}@media(max-width:900px){.dw-metrics,.dw-grid{grid-template-columns:1fr 1fr}.dw-head{align-items:start;gap:15px}}</style>
